/**
 * Settings → About → Licences: every component Boltools ships, with its full licence text.
 * The one screen allowed to name libraries (crediting them is what the licences require).
 * Data: src/core/licences.py, generated by tools_dev/collect_licences.py.
 */
const Licences = (() => {
  let data = null;

  function ensureModal() {
    let modal = document.getElementById('licences');
    if (modal) return modal;
    modal = document.createElement('div');
    modal.id = 'licences';
    modal.className = 'idt-backdrop hidden';
    modal.setAttribute('role', 'dialog');
    modal.setAttribute('aria-modal', 'true');
    modal.setAttribute('aria-labelledby', 'lic-title');
    modal.innerHTML = '<div class="idt-panel lic-panel"></div>';
    modal.addEventListener('click', onClick);
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && !modal.classList.contains('hidden')) close();
    });
    document.body.appendChild(modal);
    return modal;
  }

  function show(html, focusSelector) {
    const modal = ensureModal();
    modal.querySelector('.idt-panel').innerHTML = html;
    modal.classList.remove('hidden');
    modal.querySelector(focusSelector)?.focus();
  }

  const close = () => document.getElementById('licences')?.classList.add('hidden');

  function row(c) {
    const version = c.version ? ` ${escapeHtml(c.version)}` : '';
    const buttons = c.files.map(f =>
      `<button type="button" class="lic-file" data-lic-id="${escapeAttr(c.id)}" data-lic-file="${escapeAttr(f)}">${escapeHtml(f)}</button>`).join('');
    return `
      <li class="lic-item">
        <div class="lic-head"><strong>${escapeHtml(c.name)}${version}</strong><span>${escapeHtml(c.licence)}</span></div>
        <p>${escapeHtml(c.used_for)} · <button type="button" class="lic-link" data-lic-url="${escapeAttr(c.url)}">Project page</button></p>
        <div class="lic-files">${buttons}</div>
      </li>`;
  }

  function showList() {
    const items = data.components;
    show(`
      <h3 class="idt-title" id="lic-title">Licences</h3>
      <p class="idt-total">Boltools${data.app_version ? ` ${escapeHtml(data.app_version)}` : ''} is built on these open-source parts. Thank you to everyone who makes them.</p>
      ${items.length ? `<ul class="lic-list">${items.map(row).join('')}</ul>`
                     : '<p class="mpk-error" role="alert">The licence list could not be loaded. Please reinstall Boltools.</p>'}
      <div class="idt-actions"><button type="button" class="idt-btn idt-btn-primary" data-lic="close">Close</button></div>`,
      '[data-lic="close"]');
  }

  async function showText(compId, fileName) {
    const comp = data.components.find(c => c.id === compId);
    const text = await callBridge('read_licence', compId, fileName);
    show(`
      <h3 class="idt-title" id="lic-title">${escapeHtml(comp ? comp.name : '')}</h3>
      <p class="idt-total">${escapeHtml(fileName)}</p>
      <pre class="lic-text" tabindex="0">${escapeHtml(text || 'This licence text could not be loaded.')}</pre>
      <div class="idt-actions">
        <button type="button" class="idt-btn" data-lic="back">Back</button>
        <button type="button" class="idt-btn idt-btn-primary" data-lic="close">Close</button>
      </div>`, '[data-lic="back"]');
  }

  function onClick(e) {
    if (e.target.id === 'licences') return close();
    const el = e.target.closest('[data-lic], [data-lic-file], [data-lic-url]');
    if (!el) return;
    if (el.dataset.lic === 'close') close();
    else if (el.dataset.lic === 'back') showList();
    else if (el.dataset.licFile) showText(el.dataset.licId, el.dataset.licFile);
    else if (el.dataset.licUrl) callBridge('open_url', el.dataset.licUrl);
  }

  async function open() {
    if (!data) data = (await callBridge('get_licences')) || { components: [] };
    showList();
  }

  return { open };
})();
